// Helper function: safely extract message from various WhatsApp formats
function extractMessage(data) {
  // Check various message formats in order of priority
  const messageFormats = [
    () => data.data?.message?.conversation,
    () => data.data?.message?.extendedTextMessage?.text,
    () => data.data?.message?.buttonsResponseMessage?.selectedButtonId,
    () => data.data?.message?.listResponseMessage?.singleSelectReply?.selectedRowId
  ];

  for (const formatFn of messageFormats) {
    try {
      const message = formatFn();
      if (message) return message;
    } catch (e) {
      // Continue to next format
      continue;
    }
  }

  return '';
}

// Extract user information
const data = $input.item.json;

// Safely extract user phone
const userPhone = data.data?.key?.remoteJid?.split('@')[0] || '';
const isFromMe = data.data?.key?.fromMe || false;

// Ignore own messages
if (isFromMe || !userPhone) {
  return [];
}

// Extract message content
const message = extractMessage(data);

return [{
  json: {
    userPhone: userPhone,
    message: message.trim().toLowerCase(),
    timestamp: Date.now(),
    rawData: data
  }
}];

// Parse estado atual
let currentState = 'IDLE';
let context = {};

if ($input.item.json.value) {
  try {
    const stateData = JSON.parse($input.item.json.value);
    currentState = stateData.state || 'IDLE';
    context = stateData.context || {};
  } catch(e) {
    console.error('Erro ao parsear estado:', e);
  }
}

return [{
  json: {
    ...$input.item.json,
    currentState: currentState,
    context: context
  }
}];

// Menu Principal
const menuMessage = `👋 Olá! Bem-vindo à *Clínica Saúde Total*\n\nComo posso ajudar você hoje?\n\n*1* - 📅 Agendar consulta\n*2* - 🔄 Remarcar consulta\n*3* - ❌ Cancelar consulta\n*4* - 📞 Falar com atendente\n\n_Digite o número da opção desejada_`;

return [{
  json: {
    userPhone: $input.item.json.userPhone,
    message: menuMessage,
    nextState: 'MENU_PRINCIPAL',
    context: {}
  }
}];

// Processar escolha do menu
const choice = $input.item.json.message;
let responseMessage = '';
let nextState = 'MENU_PRINCIPAL';
let context = {};

switch(choice) {
  case '1':
    nextState = 'AGENDAMENTO_SELECAO_PROFISSIONAL';
    responseMessage = `📋 *Agendamento de Consulta*\n\nEscolha o profissional:\n\n*1* - Dr. João Silva - Cardiologista\n*2* - Dra. Maria Santos - Dermatologista\n*3* - Dr. Pedro Costa - Ortopedista\n*4* - Dra. Ana Oliveira - Pediatra\n\n_Digite o número do profissional_`;
    break;

  case '2':
    nextState = 'REMARCACAO_INICIO';
    responseMessage = `🔄 *Remarcar Consulta*\n\nBuscando suas consultas agendadas...`;
    break;

  case '3':
    nextState = 'CANCELAMENTO_INICIO';
    responseMessage = `❌ *Cancelar Consulta*\n\nBuscando suas consultas agendadas...`;
    break;

  case '4':
    nextState = 'IDLE';
    responseMessage = `📞 Transferindo para atendente...\n\nUm momento, por favor.`;
    // Aqui você pode integrar com sistema de tickets
    break;

  default:
    responseMessage = '❌ Opção inválida. Por favor, escolha uma opção de 1 a 4.';
}

return [{
  json: {
    userPhone: $input.item.json.userPhone,
    message: responseMessage,
    nextState: nextState,
    context: context
  }
}];

// Rate Limiting Check
const userPhone = $input.item.json.userPhone;

// Aqui você implementaria verificação no Redis
// Por simplicidade, apenas passa adiante

return [$input.item.json];
